--
-- Table structure for table `cajas`
--

DROP TABLE IF EXISTS `cajas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cajas` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ubicacion_id` int unsigned NOT NULL,
  `usuario_apertura_id` int unsigned NOT NULL,
  `fecha_apertura` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `monto_inicial` decimal(14,2) NOT NULL DEFAULT '0.00',
  `estado` enum('ABIERTA','CERRADA') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ABIERTA',
  `usuario_cierre_id` int unsigned DEFAULT NULL,
  `fecha_cierre` datetime DEFAULT NULL,
  `efectivo_esperado` decimal(14,2) DEFAULT NULL,
  `efectivo_real` decimal(14,2) DEFAULT NULL,
  `diferencia` decimal(14,2) DEFAULT NULL,
  `observaciones` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `abierta_flag` int unsigned GENERATED ALWAYS AS (if((`estado` = _utf8mb4'ABIERTA'),`ubicacion_id`,NULL)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_caja_abierta` (`abierta_flag`),
  KEY `fk_caja_ua` (`usuario_apertura_id`),
  KEY `fk_caja_uc` (`usuario_cierre_id`),
  KEY `idx_caja_fecha` (`ubicacion_id`,`fecha_apertura`),
  CONSTRAINT `fk_caja_ua` FOREIGN KEY (`usuario_apertura_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_caja_ubic` FOREIGN KEY (`ubicacion_id`) REFERENCES `ubicaciones` (`id`),
  CONSTRAINT `fk_caja_uc` FOREIGN KEY (`usuario_cierre_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `cajas_chk_1` CHECK ((`monto_inicial` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=161 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

