-- Table structure for table `movimientos_cuenta_corriente`
--

DROP TABLE IF EXISTS `movimientos_cuenta_corriente`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `movimientos_cuenta_corriente` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `cuenta_id` int unsigned NOT NULL,
  `fecha` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `concepto` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `debe` decimal(14,2) NOT NULL DEFAULT '0.00',
  `haber` decimal(14,2) NOT NULL DEFAULT '0.00',
  `venta_id` int unsigned DEFAULT NULL,
  `metodo_pago_id` int unsigned DEFAULT NULL,
  `usuario_id` int unsigned NOT NULL,
